function decorRank(){open('decor-rank','家园装扮值',`<p class="dialogue-text">当前装扮值 ${game.decorValue}。装修和收藏不同装扮都能增加分值；更换已拥有的装扮不会重复增加。</p><div class="reward-list">${D.decorThresholds.map((n,k)=>`<div class="reward-row"><span class="badge">${game.s.decorClaims.includes(k)?'✓':k+1}</span><div class="reward-copy"><b>${n} 装扮值${k===2?' · 解锁双倍体力':''}</b><small>金币 ${100+k*80} · 体力40${k%2?' · 卡包1':''}</small></div>${btn('领取','decor-claim',`data-index="${k}"`,'',game.s.decorClaims.includes(k)||game.decorValue<n)}</div>`).join('')}</div>`,btn('关闭','close'),'DECOR / YOUR HOME')}
function homePart(index){open('home-part',D.homeTitles[index],`${A.home(game.s)}<div class="row-buttons">${['原色晨光','薄荷海风','紫罗兰夜灯'].map((name,k)=>btn(name+(game.s.homeStyles[index]===k?' ✓':game.s.homeOwned[index].includes(k)?' · 已拥有':' · ●'+(100+k*40)),'home-decor',`data-index="${index}" data-style="${k}"`,game.s.homeStyles[index]===k?'selected':'')).join('')}</div>`,btn('重读故事','home-story',`data-index="${index}"`)+btn('关闭','close'),'HOME / '+(index+1))}
